-- Actualiza una fila existente de PeluChic. Guarda el perfil previo en el
-- log de SQL Editor (RAISE NOTICE); cópialo a un lugar privado antes de COMMIT.
-- No toca clientas, citas, miembros ni pagos. Es idempotente.
begin;
do $actualizar$
declare
  previo jsonb;
  perfil jsonb;
  menu jsonb := $menu$["Lavado personalizado~15~10~Trabajos Cotidianos Peluquería~lavado","Lavado personalizado + Corte +Secar humedad~45~28.5~Trabajos Cotidianos Peluquería~lavado-corte-secar","Lavado personalizado + Corte + Peinar~60~43.5~Trabajos Cotidianos Peluquería~lavado-corte-peinar","Peinar~40~24~Trabajos Cotidianos Peluquería~peinar","Cortar Caballero/Niño~30~19.5~Trabajos Cotidianos Peluquería~cortar-caballero-nino","Cortar Añadido a otro servicio~30~19.5~Trabajos Cotidianos Peluquería~cortar-anadido","Color de cobertura Organico~60~41.5~Trabajos Cotidianos Peluquería~color-organico","Color de cobertura en 10 minutos~50~41.5~Trabajos Cotidianos Peluquería~color-10-minutos","Baño de brillo~50~41.5~Trabajos Cotidianos Peluquería~bano-brillo","Barros tintóreos~60~65.5~Trabajos Cotidianos Peluquería~barros","Mechas*~120~46.5~Trabajos Cotidianos Peluquería~mechas","Mechas + Matiz~180~116.5~Trabajos Cotidianos Peluquería~mechas-matiz","Money piece~30~18.5~Trabajos Cotidianos Peluquería~money-piece","Matiz~40~30~Trabajos Cotidianos Peluquería~matiz","Ahuecador -Moldeados~90~45~Trabajos Cotidianos Peluquería~ahuecador","OZONOTHERAPIA~60~41~Tratamientos Cuero Cabelludo~ozonoterapia","Diagnostico capilar con cámara~20~10.5~Tratamientos Cuero Cabelludo~diagnostico-camara","Dermapen capilar sesion 30´~60~55~Tratamientos Cuero Cabelludo~dermapen","Hidrobalance capilar~60~55~Tratamientos Cuero Cabelludo~hidrobalance","barros cuero cabelludo~60~65.5~Tratamientos Cuero Cabelludo~barros-cuero-cabelludo","tratamiento de hidratacion intensiva~60~22.5~Tratamientos Cabello~hidratacion-intensiva","tratamiento de proteinas~60~36~Tratamientos Cabello~proteinas","tratamiento tipo bx~150~57~Tratamientos Cabello~tipo-bx","tratamiento olaplex~60~47~Tratamientos Cabello~olaplex","tratamiento olaplex Quelante~60~20~Tratamientos Cabello~olaplex-quelante","tratamiento reconstructor de rizos~60~26~Tratamientos Cabello~reconstructor-rizos","Nanokeratinizacion~60~42~Tratamientos Cabello~nanokeratinizacion","Hyaluroplastia~60~22~Tratamientos Cabello~hyaluroplastia","Combonano 4 sesiones en un mes~60~88~Tratamientos Cabello~combonano","barros Tratantes~60~75~Tratamientos Cabello~barros-tratantes","tratamiento keratina~120~101~Tratamientos Cabello~keratina","Tratamiento keratina PLUS~180~250~Tratamientos Cabello~keratina-plus","Spa japonés solo cabeza~60~71~Tratamientos Cabello~spa-japones-cabeza","Spa japonés cabeza y facial~120~135~Tratamientos Cabello~spa-japones-cabeza","Laminado cejas~60~28~Trabajos de la Mirada~laminado-cejas","Laminado cejas y tinte cejas~90~36~Trabajos de la Mirada~laminado-tinte-cejas","tinte de cejas~30~9~Trabajos de la Mirada~tinte-cejas","depilacion de ceja~30~12~Trabajos de la Mirada~depilacion-ceja","Linfting KOREANO pestañas~60~36~Trabajos de la Mirada~lifting-coreano","Linfting pestañas +tinte de pestañas~90~46.5~Trabajos de la Mirada~lifting-tinte","Linfting pestañas +tinte de pestañas +laminado de cejas~90~57~Trabajos de la Mirada~lifting-tinte-laminado","Linfting pestañas +tinte de pestañas +laminado de cejas+tinte de cejas~90~65~Trabajos de la Mirada~lifting-tinte-laminado-tinte","tratamiento ojos- bolsas y ojeras~60~65~Trabajos de la Mirada~ojos-bolsas-ojeras","Higiene facial hidroface~60~0~Trabajos Faciales~higiene-facial-hidroface","Ritualfacial hidroface RoseGold~75~65~Trabajos Faciales~ritual-rosegold","Ritualfacial hidroface panacee~75~65~Trabajos Faciales~ritual-panacee","Ritual hidroface~90~65~Trabajos Faciales~ritual-hidroface","Tratamiento de exosomas~60~65~Trabajos Faciales~exosomas","Dermapen facial~60~65~Trabajos Faciales~dermapen-facial","tratamiento facial Radiofrecuencia-diatermia~30~35~Trabajos Faciales~radiofrecuencia-facial","Masaje corporal~60~50~Trabajos Corporales~masajes","Masaje model shape~60~50~Trabajos Corporales~model-shape","tratamiento corporal Radiofrecuencia-diatermia~60~35~Trabajos Corporales~radiofrecuencia-corporal","Dermapen corporal~60~65~Trabajos Corporales~dermapen-corporal","Maquillaje de Correccion~45~65~Trabajos de Cámara y Foco~maquillaje-correccion","Peluqueria focos~45~65~Trabajos de Cámara y Foco~peluqueria-focos","Novias~90~150~Trabajos de Cámara y Foco~novias"]$menu$::jsonb;
begin
  -- Corrige el id estable del segundo spa (la entrada 33 de la carta).
  menu := jsonb_set(menu, '{33}', to_jsonb('Spa japonés cabeza y facial~120~135~Tratamientos Cabello~spa-japones-cabeza-facial'::text));
  select profile into previo from salons where slug = 'peluchic' for update;
  if previo is null then raise exception 'No existe salons.slug=peluchic; usa seed-peluchic.sql.'; end if;
  raise notice 'BACKUP JSON DE salons.slug=peluchic: %', previo;
  -- La fianza sigue apagada. Para activarla tras adenda: cambiar false por true.
  perfil := previo || jsonb_build_object('correoPrivacidad','mariapeluchic@gmail.com','openingHours',jsonb_build_array('Cerrado','10:00–20:00','10:00–20:00','10:00–20:00','10:00–20:00','9:00–14:00','Cerrado'),'team',jsonb_build_array('María~Gerente · peluquería, color y novias','Anca~Faciales y spa japonés','Patricia~Estética, masajes y cabina'),'teamIds',jsonb_build_array('maria','anca','patricia'),'teamHours',jsonb_build_array(jsonb_build_array('Cerrado','14:00–20:00','10:00–20:00','10:00–20:00','10:00–20:00','Cerrado','Cerrado'),jsonb_build_array('Cerrado','10:00–20:00','Cerrado','14:00–20:00','10:00–20:00','9:00–14:00','Cerrado'),jsonb_build_array('Cerrado','10:00–20:00','10:00–20:00','10:00–20:00','10:00–20:00','9:00–13:00','Cerrado')),'menu',menu,'ocultarPrecioReserva',true,'depositEnabled',false,'depositMode','hora','depositHourlyRateEur',5,'depositDeadlineHours',4,'depositAutoRelease',false,'depositAppliesTo','todas');
  -- a confirmar con María en la formación: asignación editable por categorías/ids.
  perfil := jsonb_set(perfil, '{serviciosPorProfesional}', jsonb_build_object('maria',(select jsonb_agg(split_part(v,'~',5)) from jsonb_array_elements_text(menu) v where split_part(v,'~',5) not in ('exosomas','dermapen-facial','dermapen-corporal')),'anca',(select jsonb_agg(split_part(v,'~',5)) from jsonb_array_elements_text(menu) v where (split_part(v,'~',4)='Trabajos Faciales' and split_part(v,'~',5) not in ('exosomas','dermapen-facial','dermapen-corporal')) or split_part(v,'~',5) in ('spa-japones-cabeza','spa-japones-cabeza-facial')),'patricia',(select jsonb_agg(split_part(v,'~',5)) from jsonb_array_elements_text(menu) v where split_part(v,'~',4) in ('Trabajos de la Mirada','Trabajos Faciales','Trabajos Corporales') or split_part(v,'~',5) in ('spa-japones-cabeza','spa-japones-cabeza-facial'))));
  perfil := perfil || $config${"preciosLiterales":{"higiene-facial-hidroface":"A definir, con diagnóstico"},"preguntasReserva":[{"id":"hairLength","texto":"¿Qué cantidad de pelo tienes?","tipo":"opcion","opciones":["Poco","Medio","Mucho","Excesivo"],"obligatoria":false,"activa":true,"servicios":[]},{"id":"hasColor","texto":"¿Llevas color, tintes o mechas ahora?","tipo":"opcion","opciones":["Sí","No"],"permiteOtro":true,"obligatoria":false,"activa":true,"servicios":[]},{"id":"recentChemical","texto":"¿Te has hecho algún tratamiento químico en el último mes (tinte, mechas, alisado, permanente)?","tipo":"opcion","opciones":["Sí","No"],"permiteOtro":true,"obligatoria":false,"activa":true,"servicios":[]},{"id":"color-previo","texto":"¿Has venido alguna vez a aplicarte aquí el color?","tipo":"si_no","obligatoria":false,"activa":true,"servicios":["color-organico","color-10-minutos","bano-brillo","barros","mechas","mechas-matiz","money-piece","matiz"]},{"id":"tratamiento-brillo","texto":"¿En tu retoque de color, quieres aprovechar el tiempo con un tratamiento de brillo e hidratación?","tipo":"si_no","obligatoria":false,"activa":true,"servicios":["color-organico","color-10-minutos"]}],"diasEspeciales":[{"fecha":"2026-10-12","cerrado":true},{"fecha":"2026-11-02","cerrado":true},{"fecha":"2026-11-09","cerrado":true},{"fecha":"2026-12-07","cerrado":true},{"fecha":"2026-12-08","cerrado":true},{"fecha":"2026-12-25","cerrado":true},{"fecha":"2027-01-01","cerrado":true},{"fecha":"2026-12-24","franjas":[{"inicio":"10:00","fin":"15:00"}]},{"fecha":"2026-12-31","franjas":[{"inicio":"10:00","fin":"15:00"}]},{"fecha":"2026-12-21","soloProfesionales":{"maria":[{"inicio":"10:00","fin":"20:00"}]}},{"fecha":"2026-12-23","soloProfesionales":{"anca":[{"inicio":"15:00","fin":"20:00"}]}}]}$config$::jsonb;
  perfil := perfil || jsonb_build_object('timeZone','Europe/Madrid','duracionFlexible',true);
  -- Las tres primeras preguntas se limitan a peluquería para no salir en estética.
  perfil := jsonb_set(perfil,'{preguntasReserva}',(select jsonb_agg(case when q->>'id' in ('hairLength','hasColor','recentChemical') then q || jsonb_build_object('servicios',(select jsonb_agg(split_part(v,'~',5)) from jsonb_array_elements_text(menu) v where split_part(v,'~',4) in ('Trabajos Cotidianos Peluquería','Tratamientos Cuero Cabelludo','Tratamientos Cabello','Trabajos de Cámara y Foco'))) else q end) from jsonb_array_elements(perfil->'preguntasReserva') q));
  update salons set profile=perfil, updated_at=now() where slug='peluchic';
end $actualizar$;
commit;
select slug,jsonb_array_length(profile->'menu') as servicios,profile->>'depositEnabled' as fianza_activa,updated_at from salons where slug='peluchic';
